package com.example.backend.service;
import com.example.backend.entity.Task; import com.example.backend.repository.TaskRepository; import org.junit.jupiter.api.Test; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class TaskServiceTest { @Test void togglesPersistedTask(){TaskRepository repository=mock(TaskRepository.class);Task task=new Task("Secured operation",false);when(repository.findById(3L)).thenReturn(Optional.of(task));when(repository.save(task)).thenReturn(task);assertThat(new TaskService(repository).toggleTask(3L).isCompleted()).isTrue();verify(repository).save(task);} @Test void missingTaskDoesNotWrite(){TaskRepository repository=mock(TaskRepository.class);when(repository.findById(99L)).thenReturn(Optional.empty());new TaskService(repository).toggleTask(99L);verify(repository,never()).save(any());} }
